import argparse
import re
import sys
from datetime import datetime

from .parse import parse_file
from .summary import summarise


def _date(s):
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", s):
        raise argparse.ArgumentTypeError(f"invalid date: {s!r} (expected YYYY-MM-DD)")
    try:
        return datetime.strptime(s, "%Y-%m-%d").date()
    except ValueError:
        raise argparse.ArgumentTypeError(f"invalid date: {s!r} (expected YYYY-MM-DD)")


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(prog="logsum", description="Summarise an access log.")
    ap.add_argument("logfile")
    ap.add_argument("--top", type=int, default=5, help="number of paths to list")
    ap.add_argument("--since", type=_date, metavar="YYYY-MM-DD",
                    help="only count requests on or after this date")
    ap.add_argument("--until", type=_date, metavar="YYYY-MM-DD",
                    help="only count requests on or before this date")
    a = ap.parse_args(argv)

    def in_range(r):
        d = r.ts.date()
        if a.since and d < a.since:
            return False
        if a.until and d > a.until:
            return False
        return True

    print(summarise((r for r in parse_file(a.logfile) if in_range(r)), top=a.top))
    return 0


if __name__ == "__main__":
    sys.exit(main())
